    "packingContents": "1 × Cooling & Charging Stand; 4 × Type-CCharging Connector; 1 × Headset Holder; 1 × Mounting Screws",
    "desc": "This multifunctional cooling stand is designed for the full lineup of PS5 consoles, compatible with PS5 Slim Disc & Digital Edition, original PS5 Disc & Digital Edition, as well as PS5 Pro Disc and Digital Edition. It adopts a modular design with removable baffles. Simply replace the baffles to fit different console models. Easy to install and firmly holds your console in place to prevent tipping, one dock works for multiple versions.\n\nEquipped with dual‑turbo high‑speed cooling fans, the stand supports touch control with three modes: low speed, high speed and power‑off. It continuously dissipates heat generated during gaming, stabilizes the console temperature, reduces hardware wear from long‑hour gameplay and extends the service life of your PS5. The base plate is made of aluminum alloy, water‑resistant and anti‑corrosion. Thickened non‑slip buffer pads keep the stand firmly anchored on your desk without sliding during intense gaming sessions.\n\nMore than a cooling bracket, it serves as an all‑in‑one gaming organizer. Built‑in dual charging slots power up two PS5 controllers simultaneously and fully charge them within 2‑4 hours. Red and green LED indicators clearly show charging status at a glance. It also comes with a headset hanger and game disc storage slots to neatly arrange your headphones and game cases. Tidy up your messy gaming desk and free up plenty of desktop space.\n\nThe stand features dual USB‑A plus one Type‑C expansion ports for connecting extra gaming peripherals and solving the problem of insufficient ports. It combines console cooling, dual controller fast charging, accessory storage and USB hub functions in one sleek unit. With a clean modern look that matches your gaming setup, this dock is an essential upgrade accessory for every PS5 gamer.",
