    "packingContents": "1 × Cooling Stand; 1 × Mounting Screws; 2 × Horizontal Hooks",
    "desc": "This multifunctional cooling stand is specially designed for the PS5 Slim console. It integrates cooling system, dual controller charging docks, game disc storage, headset hanger and expansion ports, offering an all‑in‑one solution to organize your gaming setup.\nEquipped with cooling fans and a touch control panel, the stand delivers powerful airflow to quickly dissipate heat from your PS5 Slim. It prevents thermal throttling and maintains stable performance even during long‑hour gaming sessions.\n\nIt features dual charging stations for PS5 controllers with clear LED charging indicators. The red light stays on while charging, and turns green when fully charged or idle. Red and green lights flash alternately when battery level reaches 95%‑100%, letting you check power status at a glance.\nBuilt‑in headset hook and a storage slot for up to 6 game discs keep your accessories neatly arranged and free your desk from clutter.\n\nNon‑slip silicone foot pads and a screw fixing hole on the bottom secure your console firmly and prevent slipping. It comes with one USB output port and a Type‑C input & output port, supporting external power supply and extra device charging for wider usability.\nWith a minimalist white design that matches the original style of PS5 Slim, this stand is not only a practical gaming accessory but also an elegant desktop decor. Upgrade your PS5 Slim with a tidy, efficient and complete gaming ecosystem.",
