    "packingContents": "1 × Cooling Stand; 1 × Charging Stand; 2 × Hooks",
    "desc": "This multifunctional wall‑mounted cooling bracket is specially designed for PS5 and PS5 Slim, compatible with both disc and digital editions. Built with sturdy metal material, it is solid, stable and long‑lasting for daily gaming use. Equipped with a dual‑channel cooling system featuring two powerful whirlpool fans, it offers three adjustable wind speeds (Low / Medium / High) with one‑button control to quickly dissipate accumulated heat from your console, preventing overheating and throttling during long gaming sessions and greatly improving your gaming experience. The station comes with dual controller charging docks with clear LED charging indicators: orange light means charging, while blue light shows fully charged or idle status, letting you check power status at a glance. It also features customizable RGB colorful lighting effects with multiple light modes, adding a cool and immersive gaming atmosphere to your setup. Besides cooling and charging functions, this all‑in‑one rack provides dedicated storage hooks for headsets and VR headsets, plus extra USB charging ports for more device charging needs. Mount your PlayStation console on the wall to save desk space, keep your gaming area neat and tidy, and organize your console, gamepads and headsets all in one place. It is an ideal comprehensive gaming accessory for every PS5 gamer.",
