    "desc": "This multifunctional RGB cooling stand is specially designed for PS5 Slim and PS5 Pro consoles, compatible with both Disc and Digital Editions. It integrates active cooling, dual controller charging, game disc storage, headset hanging and extra USB ports into one sleek all‑in‑one gaming station, perfectly organizing your gaming setup.\nEquipped with an active downward‑draft cooling system with 3 adjustable fan speeds (Low / Medium / High), it quickly draws hot air away from the bottom of the console for efficient heat dissipation, preventing overheating and throttling during long‑hour gaming sessions.\nThe station features dual charging docks to charge two PS5 controllers simultaneously. Clear LED indicators show the charging status: orange light while charging, blue light when fully charged or idle. Stunning customizable RGB ambient lighting with 4 lighting modes creates an immersive gaming atmosphere, and you can easily switch light effects via the touch control button.\nThoughtful practical details greatly improve usability. Two extra USB ports support device charging and data transfer. Non‑slip silicone pads on the bottom keep the whole stand stable. Built‑in positioning screws lock the console firmly in place. A removable game card rack stores up to 8 game discs neatly, and a headset hook offers convenient headphone storage.\nSay goodbye to messy cables and scattered gaming accessories. This multi‑purpose PS5 Slim / PS5 Pro cooling charging dock protects your console, keeps everything tidy and upgrades your gaming experience.",
